select "p".*, ST_AsText(ST_Transform(ST_GeomFromText("p"."geometry", ?), 4326)) as "geospatial:4326" from (select (CASE WHEN ("occurrences"."region" = ?) THEN "occurrences"."id" END) AS "id", (CASE WHEN ("occurrences"."region" = ?) THEN st_astext("occurrences"."geometry") END) AS "geometry" from "occurrences" where "occurrences"."region" = ? and ST_DWithin("occurrences"."geometry", ST_Transform(ST_SetSRID(ST_MakePoint(?, ?), 4326), ?::integer)::geography, ?)) as "p" where "p"."geometry" is not null order by "p"."id" asc limit ?
-- bindings: [4674,"south","south","south",-46.7,-23.65,4674,10000,100]
